(async()=>{const fonts=await figma.listAvailableFontsAsync();const candidates={SimSun:['SimSun','Songti SC','Noto Serif CJK SC','Noto Serif SC'],Georgia:['Georgia','Times New Roman','Noto Serif'],'Microsoft YaHei':['Microsoft YaHei','PingFang SC','Noto Sans CJK SC','Noto Sans SC']};let x=0;const nodes=[];const fallbacks=new Set();for(const b of boards){const n=figma.createNodeFromSvg(b.svg.replace(/<text\b[^>]*>[\s\S]*?<\/text>/g,''));n.name=b.name;n.x=x;n.y=0;for(const t of b.texts){const names=candidates[t.family]||[t.family];let f;for(const name of names){f=fonts.find(z=>z.fontName.family===name&&['Regular','Book','Normal','W3'].includes(z.fontName.style));if(f)break;}if(!f){f=fonts.find(z=>z.fontName.family==='Inter'&&z.fontName.style==='Regular')||fonts[0];fallbacks.add(t.family)}await figma.loadFontAsync(f.fontName);const text=figma.createText();text.fontName=f.fontName;text.fontSize=t.size;text.characters=t.text;text.name=t.text;text.textAutoResize='WIDTH_AND_HEIGHT';const c=t.color.slice(1);text.fills=[{type:'SOLID',color:{r:parseInt(c.slice(0,2),16)/255,g:parseInt(c.slice(2,4),16)/255,b:parseInt(c.slice(4,6),16)/255}}];n.appendChild(text);text.x=t.x;text.y=t.y-t.size*.88;}nodes.push(n);x+=b.width+120}figma.currentPage.selection=nodes;figma.viewport.scrollAndZoomIntoView(nodes);figma.closePlugin('已导入两套画板，文字与矢量均可编辑。'+(fallbacks.size?'部分字体已替换，请检查中文字体。':''))})().catch(e=>figma.closePlugin('导入失败：'+e.message));